-- ===========================================================================
-- india_b2b_workflows.sql — six ready-to-run workflows for Indian B2B buyers
--
-- Run in the Supabase dashboard: SQL Editor -> New query -> paste -> Run.
-- Safe to run more than once: every row is 'on conflict do nothing', so a
-- second run adds nothing and never overwrites edits made on the canvas.
--
-- GENERATED by scripts/seed-india-workflows.mjs. Edit the script, not this
-- file. Mechanism and rules are identical to b2b_workflows.sql — ownership
-- resolved from the admins table, est_credits/est_duration_ms/est_partial/
-- models deliberately left for the server to derive from the stored graph.
-- ===========================================================================

begin;

do $seed$
declare
  v_owner uuid;
  v_count integer;
begin
  select user_id into v_owner from public.admins where id = 1;

  if v_owner is null then
    raise exception
      'No admin seeded. Run: select public.set_admin(''you@example.com'');';
  end if;

  insert into public.projects (
    id, user_id, name, description, node_count,
    workflow_json, edge_style, incurred_cost
  )
  select
    s.id, v_owner, s.name, s.description, s.node_count,
    s.workflow_json, 'curved', 0
  from (values
  (
    'wf_seed_in_marketplace_pack',
    'Marketplace Listing Pack',
    'One phone photo of a product into a marketplace-ready set: a pure-white hero for Amazon.in/Flipkart, a lifestyle scene, and a 4:5 mobile-first shot. Upload your product photo — every prompt is written to reproduce it exactly, because a listing that redraws the product is a returns problem.',
    8,
    '{"version":1,"id":"wf_seed_in_marketplace_pack","name":"Marketplace Listing Pack","directoryPath":"cloud:wf_seed_in_marketplace_pack","nodes":[{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":340},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"prompt-1","type":"prompt","position":{"x":50,"y":40},"data":{"prompt":"HERO — the marketplace main image.\n\nPlace the attached product on a pure white background (RGB 255,255,255), for an Amazon.in / Flipkart main listing image.\n\nThe photo is evidence, not raw material:\n- Reproduce the product exactly — shape, colour, texture, stitching, engraving. Do not redraw, restyle or invent any part of it\n- Every label and marking on the product must stay legible and unchanged\n\nFrame and light:\n- The product fills roughly 80% of the frame, centred, fully in frame\n- Soft studio light from upper left, a faint natural contact shadow beneath — nothing else\n- No props, no text, no logos, no watermarks, no reflections of other objects\n- The result must read cleanly as a thumbnail in search results"},"style":{"width":320,"height":220}},{"id":"prompt-2","type":"prompt","position":{"x":50,"y":640},"data":{"prompt":"LIFESTYLE — the second listing image.\n\nPlace the attached product, reproduced exactly as photographed, into one believable Indian home setting where it would actually be used — a sunlit apartment table, a tidy kitchen counter, a balcony shelf. One setting, chosen to fit the product.\n\n- The product stays the unmistakable subject, sharp and true to the photo; the scene stays soft behind it\n- Warm, natural late-morning light; believable, not aspirational-glossy\n- No people''s faces, no brand marks in the scene, no rendered text anywhere\n- Composed centrally so a square crop loses nothing important"},"style":{"width":320,"height":220}},{"id":"prompt-3","type":"prompt","position":{"x":50,"y":940},"data":{"prompt":"MOBILE PORTRAIT — the swipe-deck shot.\n\nA 4:5 portrait of the attached product, reproduced exactly, shot as a tight three-quarter angle against a single flat colour that complements the product — one confident colour, no gradient, no pattern.\n\n- Product large in frame, angled to show depth and material\n- Soft rim light separating it from the backdrop, gentle shadow below\n- Leave the top fifth of the frame quiet, in case a headline is set over it later\n- No text, no logos, no props"},"style":{"width":320,"height":220}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":450,"y":30},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":450,"y":380},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-3","type":"nanoBanana","position":{"x":450,"y":730},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":850,"y":340},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-2","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-2","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-3","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-3","targetHandle":"image"},{"id":"edge-prompt-1-nanoBanana-1","source":"prompt-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-prompt-2-nanoBanana-2","source":"prompt-2","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-prompt-3-nanoBanana-3","source":"prompt-3","sourceHandle":"text","target":"nanoBanana-3","targetHandle":"text"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-3-outputGallery-1","source":"nanoBanana-3","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
