  (
    'wf_seed_in_festive_campaign',
    'Festive Campaign Pack',
    'The same product re-dressed for the festive calendar — edit one line to switch Diwali for Holi, Rakhi, Eid or Onam. The LLM node turns your brief into festival art direction; the brief bans deities and rendered text outright, so every output is brand-safe and the greeting is set as live text later. Renders a 1:1 feed card and a 9:16 story.',
    6,
    '{"version":1,"id":"wf_seed_in_festive_campaign","name":"Festive Campaign Pack","directoryPath":"cloud:wf_seed_in_festive_campaign","nodes":[{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":60},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"prompt-1","type":"prompt","position":{"x":50,"y":390},"data":{"prompt":"Art-direct a festive campaign image for an Indian D2C brand.\n\nFestival: Diwali   ← edit this line to re-run the same product for Holi, Raksha Bandhan, Eid or Onam\nThe product: whatever is attached — it must be reproduced exactly as photographed, never redrawn\nThe occasion''s job: make the product feel like this festival''s natural purchase or gift\n\nWrite one image prompt. Hold to these:\n- Festive dressing through decorative motifs only — diyas, marigold strings, rangoli patterns, paper lanterns, fairy lights, gulal colour for Holi. NEVER deities, idols or religious symbols\n- The product stays the hero, sharp and unaltered, in the front third; the festive scene glows behind it, softly out of focus\n- Warm celebratory light appropriate to the festival named above\n- No rendered text, no logos, no greeting — the wishes are set as live text later, so leave the upper third calm and uncluttered\n- Rich but not gaudy: two dominant festive colours, chosen for the festival, plus the product''s own\n- Check it still reads at thumbnail size"},"style":{"width":320,"height":220}},{"id":"llmGenerate-1","type":"llmGenerate","position":{"x":430,"y":320},"data":{"inputPrompt":null,"inputImages":[],"outputText":null,"provider":"google","model":"gemini-3-flash-preview","temperature":0.7,"maxTokens":8192,"status":"idle","error":null},"style":{"width":320,"height":360}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":810,"y":120},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":810,"y":470},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"9:16","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":1210,"y":280},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-prompt-1-llmGenerate-1","source":"prompt-1","sourceHandle":"text","target":"llmGenerate-1","targetHandle":"text"},{"id":"edge-llmGenerate-1-nanoBanana-1","source":"llmGenerate-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-llmGenerate-1-nanoBanana-2","source":"llmGenerate-1","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-2","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-2","targetHandle":"image"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  ),
  (
    'wf_seed_in_ab_creative_matrix',
    'A/B Creative Matrix (D2C)',
    'One product, three selling angles — desire, trust and value — each a separate 4:5 ad creative for a paid social test. Three deliberate prompts rather than one brief fanned out: three samples of one prompt vary by seed and test the model, not the message. Wire your product photo in once; it feeds all three.',
    8,
    '{"version":1,"id":"wf_seed_in_ab_creative_matrix","name":"A/B Creative Matrix (D2C)","directoryPath":"cloud:wf_seed_in_ab_creative_matrix","nodes":[{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":400},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"prompt-1","type":"prompt","position":{"x":430,"y":40},"data":{"prompt":"ANGLE 1 — desire.\n\nFor a paid social test for an Indian D2C product. The attached product, reproduced exactly, staged as the object of want: dramatic single-source light against deep charcoal, shallow depth, one glinting highlight tracing its edge. Premium and unhurried — the ad equivalent of picking it up in a store.\n\nNo text, no logos, no price, no people. 4:5 feed card, lower third left quiet for a headline set later."},"style":{"width":320,"height":220}},{"id":"prompt-2","type":"prompt","position":{"x":430,"y":380},"data":{"prompt":"ANGLE 2 — trust.\n\nSame product, sold on credibility — the angle that answers \"will the real thing look like the photo?\"\n\nThe attached product, reproduced exactly, laid out plainly in bright even daylight on a clean neutral surface, straight-on and honest, every material and seam visible, nothing hidden by styling. The composition of a careful unboxing photo, elevated by perfect light.\n\nNo text, no logos, no badges or seals — trust is conveyed by clarity, never by invented marks. 4:5, lower third quiet."},"style":{"width":320,"height":220}},{"id":"prompt-3","type":"prompt","position":{"x":430,"y":720},"data":{"prompt":"ANGLE 3 — value.\n\nSame product, sold on everyday worth: the attached product, reproduced exactly, in mid-use context in an ordinary Indian household morning — surrounded by the small real things of a daily routine, warm believable light, nothing aspirational or staged-looking.\n\nThe product is the one sharp, saturated element; the routine around it is soft. No faces, no text, no logos, no invented price tags. Same 4:5 frame, lower third quiet, so the three angles read as one campaign."},"style":{"width":320,"height":220}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":810,"y":30},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":810,"y":380},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-3","type":"nanoBanana","position":{"x":810,"y":730},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":1210,"y":350},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-2","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-2","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-3","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-3","targetHandle":"image"},{"id":"edge-prompt-1-nanoBanana-1","source":"prompt-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-prompt-2-nanoBanana-2","source":"prompt-2","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-prompt-3-nanoBanana-3","source":"prompt-3","sourceHandle":"text","target":"nanoBanana-3","targetHandle":"text"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-3-outputGallery-1","source":"nanoBanana-3","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
