  (
    'wf_seed_in_jewellery_tryon',
    'Jewellery Try-On + Detail',
    'A flat product shot of a piece and a model reference into a worn shot, then a macro detail crop chained off the result. Both inputs are evidence: the piece must survive stone-for-stone and the model must stay recognisably themselves — identity drift is the #1 complaint with AI jewellery shots, so both prompts spend most of their words forbidding it.',
    7,
    '{"version":1,"id":"wf_seed_in_jewellery_tryon","name":"Jewellery Try-On + Detail","directoryPath":"cloud:wf_seed_in_jewellery_tryon","nodes":[{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":60},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"imageInput-2","type":"imageInput","position":{"x":50,"y":390},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"prompt-1","type":"prompt","position":{"x":50,"y":720},"data":{"prompt":"Composite the attached jewellery piece onto the attached model, worn naturally, for a premium catalogue shot.\n\nBoth inputs are evidence, not raw material:\n- The piece must survive exactly — every stone, link, prong and engraving in its photographed position, its metal colour unchanged. Do not simplify, symmetrise or re-set it\n- The model''s face, skin tone and features stay recognisably their own. Do not beautify or drift their identity\n\nStaging:\n- Neck, ear or wrist framing as the piece dictates; the piece in tack-sharp focus, catching the key light\n- Elegant dark neutral backdrop, jewellery-store key lighting with soft fill\n- Natural wear: correct drape, weight and skin contact\n- No text, no logos. 4:5 portrait"},"style":{"width":320,"height":220}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":450,"y":340},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"prompt-2","type":"prompt","position":{"x":450,"y":720},"data":{"prompt":"From the attached worn shot, a macro detail crop of the piece itself: fill the square frame with its most intricate section, same lighting, same angle of wear, background melting to soft darkness.\n\nReproduce the piece exactly as it appears in the input — this crop exists to prove the craftsmanship, so no invented facets, no added sparkle effects, no text."},"style":{"width":320,"height":220}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":850,"y":340},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":1250,"y":320},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-imageInput-2-nanoBanana-1","source":"imageInput-2","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-prompt-1-nanoBanana-1","source":"prompt-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-nanoBanana-1-nanoBanana-2","source":"nanoBanana-1","sourceHandle":"image","target":"nanoBanana-2","targetHandle":"image"},{"id":"edge-prompt-2-nanoBanana-2","source":"prompt-2","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  ),
  (
    'wf_seed_in_menu_glam',
    'Menu Glam (Restaurants)',
    'A phone photo of a dish into two listing-ready shots: a square delivery-app tile and a wide menu banner. The dish itself is reproduced exactly — a listing photo that invents garnish sells a plate the kitchen doesn''t serve, which is a refunds problem, so both prompts upgrade only the plate, surface and light around it.',
    6,
    '{"version":1,"id":"wf_seed_in_menu_glam","name":"Menu Glam (Restaurants)","directoryPath":"cloud:wf_seed_in_menu_glam","nodes":[{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":300},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"prompt-1","type":"prompt","position":{"x":50,"y":20},"data":{"prompt":"DELIVERY TILE — the Swiggy/Zomato listing square.\n\nRe-stage the attached dish for a delivery-app listing photo.\n\nThe food is evidence:\n- The dish itself — its components, quantity, colour and arrangement — must match the photo. Do not add garnish, portions or ingredients the kitchen does not serve\n\nUpgrade only what surrounds it:\n- A clean, appealing plate or bowl suited to the cuisine, on a warm neutral surface\n- Soft directional daylight from the side, gentle steam if the dish is hot\n- Shot from 45 degrees, dish filling most of the square frame\n- Appetising and true — no text, no logos, no cutlery clutter"},"style":{"width":320,"height":220}},{"id":"prompt-2","type":"prompt","position":{"x":50,"y":600},"data":{"prompt":"MENU BANNER — the wide header shot.\n\nThe same attached dish, reproduced exactly, as a 16:9 banner: dish placed in the right half of the frame on a rustic table styled sparely to match the cuisine, left half falling into soft warm bokeh where the restaurant''s name will be set as live text later.\n\n- Same rule: nothing on the plate that isn''t in the photo\n- Low warm evening light, inviting, slight top-down angle\n- No rendered text, no logos, no people"},"style":{"width":320,"height":220}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":450,"y":30},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":450,"y":430},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"16:9","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":850,"y":220},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-2","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-2","targetHandle":"image"},{"id":"edge-prompt-1-nanoBanana-1","source":"prompt-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-prompt-2-nanoBanana-2","source":"prompt-2","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  ),
  (
    'wf_seed_in_whatsapp_pack',
    'WhatsApp Catalogue + Status',
    'One SKU into the two images an Indian SMB actually sends: a clean 1:1 catalogue card and a 9:16 status frame. The LLM node writes matched art direction for both from one line about the product and the offer — the price and offer text are added as stickers or live text on top, never rendered into the image, so one render survives every price change.',
    6,
    '{"version":1,"id":"wf_seed_in_whatsapp_pack","name":"WhatsApp Catalogue + Status","directoryPath":"cloud:wf_seed_in_whatsapp_pack","nodes":[{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":60},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"prompt-1","type":"prompt","position":{"x":50,"y":390},"data":{"prompt":"Art-direct a two-image WhatsApp set for one product.\n\nThe product: whatever is attached — reproduced exactly as photographed, never redrawn.\nThe offer, for context only: a limited festive price. Do NOT render the offer, a price, or any text into either image — stickers and captions go on top later, and a render with baked-in text dies at the first price change.\n\nWrite ONE image prompt that works at both 1:1 and 9:16. Hold to these:\n- The product centred and large against a single fresh, saleable backdrop colour that flatters it — flat or barely gradient, nothing competing\n- Soft even light, crisp contact shadow, catalogue-clean\n- Compose centrally with generous margin above and below, so the 9:16 gains calm space (for the status caption) and the 1:1 crops clean\n- No text, no logos, no stickers, no burst shapes — those are added after\n- It must read instantly on a low-end phone screen in sunlight: high contrast, no subtle detail carrying the message"},"style":{"width":320,"height":220}},{"id":"llmGenerate-1","type":"llmGenerate","position":{"x":430,"y":320},"data":{"inputPrompt":null,"inputImages":[],"outputText":null,"provider":"google","model":"gemini-3-flash-preview","temperature":0.7,"maxTokens":8192,"status":"idle","error":null},"style":{"width":320,"height":360}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":810,"y":120},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":810,"y":470},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"9:16","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":1210,"y":280},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-prompt-1-llmGenerate-1","source":"prompt-1","sourceHandle":"text","target":"llmGenerate-1","targetHandle":"text"},{"id":"edge-llmGenerate-1-nanoBanana-1","source":"llmGenerate-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-llmGenerate-1-nanoBanana-2","source":"llmGenerate-1","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-imageInput-1-nanoBanana-2","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-2","targetHandle":"image"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  )
  ) as s(id, name, description, node_count, workflow_json)
  on conflict (id) do nothing;

  get diagnostics v_count = row_count;
  raise notice 'Seeded % workflow(s) for owner %.', v_count, v_owner;
end
$seed$;

commit;

